  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (p.endsWith('.jsonl') && p.split(path.sep).includes('sessions')) files.push(p);
  }
})('fixtures/codex-0.151.0-alpha.7.2');
let calls = 0;
const st = {};
const byType = {};
for (const p of files) {
  for (const l of fs.readFileSync(p, 'utf8').split('\n')) {
    if (!l.trim()) continue;
    let o;
    try { o = JSON.parse(l); } catch (e) { continue; }
    const pl = o.payload;
    if (!pl || typeof pl !== 'object') continue;
    const t = pl.type;
    if (t === 'function_call' || t === 'custom_tool_call' || t === 'local_shell_call') {
      calls += 1;
      byType[t] = (byType[t] || 0) + 1;
      const s = pl.status === undefined ? '(absent)' : String(pl.status);
      st[s] = (st[s] || 0) + 1;
    }
  }
}
console.log('files', files.length, 'tool calls', calls, 'byType', JSON.stringify(byType), 'status', JSON.stringify(st));

