  try {
    const rows = db.prepare('SELECT id, parent_id, model, cost, time_created FROM session').all();
    const parts = db.prepare('SELECT id, session_id, message_id, data FROM part ORDER BY id').all();
    const bySession = new Map();
    for (const p of parts) {
      if (!bySession.has(p.session_id)) bySession.set(p.session_id, []);
      bySession.get(p.session_id).push(p);
    }
    // One SessionState per ROOT session; children become subagents.
    const children = new Map();
    for (const r of rows) {
      if (r.parent_id) {
        if (!children.has(r.parent_id)) children.set(r.parent_id, []);
        children.get(r.parent_id).push(r);
      }
    }
    for (const root of rows.filter((r) => !r.parent_id)) {
      const agents = [];
      const compactions = [];
      let cost = num(root.cost);
      const build = (row, kind) => {
        const tools = [];
        const usageSeries = [];
        let ordinal = 0;
        for (const p of bySession.get(row.id) ?? []) {
          let d;
          try {
            d = JSON.parse(p.data);
          } catch {
            continue;
          }
          if (d.type === 'tool' && typeof d.tool === 'string') {
            const st = d?.state?.status;
            const time = d?.state?.time;
            tools.push({
              id: typeof d.callID === 'string' ? d.callID : p.id,
              ordinal: ordinal++,
              toolName: d.tool,
              toolClass: classOf(d.tool),
              filePath: filePathOf(d.tool, d?.state?.input),
              inputHash: inputHash(d?.state?.input ?? null),
              status: st === 'error' ? 'error' : st === 'completed' ? 'done' : st === 'running' ? 'running' : 'unknown',
              durationMs: time && num(time.end) > 0 && num(time.start) > 0 ? num(time.end) - num(time.start) : undefined,
            });
          } else if (d.type === 'step-finish') {
            const t = d.tokens ?? {};
            usageSeries.push({
              ordinal: usageSeries.length,
              input: num(t.input),
              cacheCreation: num(t?.cache?.write),
              cacheRead: num(t?.cache?.read),
              output: num(t.output),
            });
            cost += num(d.cost);
          } else if (d.type === 'compaction') {
            compactions.push({ ordinal: tools.length, trigger: 'engine', promptBefore: undefined, promptAfter: undefined });
          }
        }
        agents.push({ agentId: row.id, kind, tools, usageSeries });
      };
      build(root, 'main');
      for (const c of children.get(root.id) ?? []) build(c, 'subagent');
      sessions.push({
        corpus, engine: 'opencode', sessionId: root.id, schemaOk: true, parked: [],
        model: typeof root.model === 'string' ? root.model : undefined,
        costUsd: num(root.cost) > 0 ? num(root.cost) : undefined,
        costSource: num(root.cost) > 0 ? 'engine' : undefined,
        compactions, agents, malformed: 0,
      });
    }
  } finally {
    db.close();
  }
  return sessions;
}

