import fs from 'node:fs';
const j = JSON.parse(fs.readFileSync('lab/docs/evidence/phase-0-stats/facts.json', 'utf8'));
const byEngine = {};
let all = [];
for (const f of j.facts) {
  if (f.corpus.startsWith('synthetic-')) continue;
  const d = (f.F7 && f.F7.deltas) || [];
  byEngine[f.engine] = (byEngine[f.engine] || []).concat(d);
  all = all.concat(d);
}
const p = (arr, q) => {
  if (arr.length === 0) return null;
  const s = [...arr].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor(q * s.length))];
};
const qualify = (arr, t) => arr.filter((x) => x >= t).length;
for (const [e, arr] of Object.entries(byEngine)) {
  console.log(e, 'n=' + arr.length, 'nonZero=' + arr.filter((x) => x > 0).length,
    'p95=' + p(arr, 0.95), 'max=' + Math.max(0, ...arr),
    '>=4000:' + qualify(arr, 4000), '>=3000:' + qualify(arr, 3000));
}
console.log('ALL captured n=' + all.length, 'nonZero=' + all.filter((x) => x > 0).length,
  'p95=' + p(all, 0.95), '>=4000:' + qualify(all, 4000) + ' (' + (100 * qualify(all, 4000) / all.length).toFixed(1) + '%)',
  '>=3000:' + qualify(all, 3000) + ' (' + (100 * qualify(all, 3000) / all.length).toFixed(1) + '%)');
const cc = byEngine.cc || [];
console.log('CC-only: >=4000 is ' + (100 * qualify(cc, 4000) / cc.length).toFixed(1) + '%; p95=' + p(cc, 0.95));

